//! Cargo-driven `netapi32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is netapi32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x79360000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff95000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff95000000u64)),
        o => panic!("netapi32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "engine:pseh", "import:samlib", "import:secur32", "import:iphlpapi", "import:ws2_32", "import:advapi32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "engine:oldnames"],
        "x86_64" => &["body", "engine:wine", "engine:pseh", "import:samlib", "import:secur32", "import:iphlpapi", "import:ws2_32", "import:advapi32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "aarch64" => &["body", "engine:wine", "engine:pseh", "import:samlib", "import:secur32", "import:iphlpapi", "import:ws2_32", "import:advapi32", "import:rpcrt4", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("netapi32-rust")
        .c_from_compile_db("netapi32_shims", &["dll/win32/netapi32/atsvc_c.c", "dll/win32/netapi32/browser_c.c", "dll/win32/netapi32/dssetup_c.c", "dll/win32/netapi32/netdfs_c.c", "dll/win32/netapi32/netlogon_c.c", "dll/win32/netapi32/srvsvc_c.c", "dll/win32/netapi32/wkssvc_c.c"])
        .spec2def("dll/win32/netapi32/netapi32.spec", "netapi32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/samlib/samlib.spec", "samlib.dll", "samlib")
        .delay_import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
